{
  "name": "Car Fuel Consumption Tracker",
  "description": "An advanced, aesthetically pleasing React application to track car fuel consumption, calculate costs, and visualize efficiency trends using Gemini AI for insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface FuelRecord {
  id: string;
  date: string;
  odometer: number;
  liters: number;
  pricePerLiter: number;
  totalCost: number;
}

export interface Statistics {
  totalDistance: number;
  totalLiters: number;
  totalCost: number;
  averageConsumption: number; // liters per 100km
  costPerKm: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { FuelRecord, Statistics } from './types';
import Dashboard from './components/Dashboard';
import RecordForm from './components/RecordForm';
import HistoryTable from './components/HistoryTable';
import AIInsights from './components/AIInsights';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [records, setRecords] = useState<FuelRecord[]>(() => {
    const saved = localStorage.getItem('fuel_records');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('fuel_records', JSON.stringify(records));
  }, [records]);

  const stats = useMemo((): Statistics => {
    if (records.length < 2) {
      return { totalDistance: 0, totalLiters: 0, totalCost: 0, averageConsumption: 0, costPerKm: 0 };
    }

    const sorted = [...records].sort((a, b) => a.odometer - b.odometer);
    const totalDistance = sorted[sorted.length - 1].odometer - sorted[0].odometer;
    const totalLiters = sorted.slice(1).reduce((acc, curr) => acc + curr.liters, 0);
    const totalCost = sorted.reduce((acc, curr) => acc + curr.totalCost, 0);

    const averageConsumption = totalDistance > 0 ? (totalLiters / totalDistance) * 100 : 0;
    const costPerKm = totalDistance > 0 ? totalCost / totalDistance : 0;

    return { totalDistance, totalLiters, totalCost, averageConsumption, costPerKm };
  }, [records]);

  const addRecord = (data: Omit<FuelRecord, 'id' | 'totalCost'>) => {
    const newRecord: FuelRecord = {
      ...data,
      id: uuidv4(),
      totalCost: data.liters * data.pricePerLiter
    };
    setRecords(prev => [...prev, newRecord].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };

  const deleteRecord = (id: string) => {
    setRecords(prev => prev.filter(r => r.id !== id));
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-12">
      <header className="bg-gradient-to-r from-blue-700 to-indigo-800 text-white py-8 px-4 shadow-lg mb-8">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <i className="fas fa-gas-pump text-3xl"></i>
            </div>
            <div>
              <h1 className="text-3xl font-bold tracking-tight">حاسبة استهلاك البنزين</h1>
              <p className="text-blue-100 opacity-80">تتبع مصاريف سيارتك وحسن كفاءة الاستهلاك</p>
            </div>
          </div>
          <div className="bg-white/10 px-6 py-2 rounded-full border border-white/20">
             {records.length} تم تسجيل {records.length === 1 ? 'مرة واحدة' : 'مرات'}
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left Column: Form & AI */}
        <div className="lg:col-span-4 space-y-8">
          <RecordForm onAdd={addRecord} lastOdometer={records[0]?.odometer || 0} />
          <AIInsights records={records} stats={stats} />
        </div>

        {/* Right Column: Dashboard & Table */}
        <div className="lg:col-span-8 space-y-8">
          <Dashboard stats={stats} />
          <HistoryTable records={records} onDelete={deleteRecord} />
        </div>
      </main>

      <footer className="mt-16 text-center text-slate-400 text-sm">
        <p>تم التطوير بكل حب لمساعدتك في توفير الوقود</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { Statistics } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

interface Props {
  stats: Statistics;
}

const Dashboard: React.FC<Props> = ({ stats }) => {
  const cards = [
    { label: 'متوسط الاستهلاك', value: `${stats.averageConsumption.toFixed(2)} لتر/100كم`, icon: 'fa-tachometer-alt', color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'إجمالي المسافة', value: `${stats.totalDistance.toLocaleString()} كم`, icon: 'fa-road', color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'تكلفة الكيلومتر', value: `${stats.costPerKm.toFixed(2)} ج.م`, icon: 'fa-coins', color: 'text-amber-600', bg: 'bg-amber-50' },
    { label: 'إجمالي المصاريف', value: `${stats.totalCost.toLocaleString()} ج.م`, icon: 'fa-wallet', color: 'text-rose-600', bg: 'bg-rose-50' },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {cards.map((card, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-5 transition-transform hover:scale-[1.02]">
            <div className={`${card.bg} ${card.color} w-14 h-14 rounded-xl flex items-center justify-center text-2xl`}>
              <i className={`fas ${card.icon}`}></i>
            </div>
            <div>
              <p className="text-slate-500 text-sm font-medium">{card.label}</p>
              <h3 className="text-xl font-bold text-slate-800">{card.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-[300px]">
        <h4 className="text-slate-700 font-bold mb-4 flex items-center gap-2">
          <i className="fas fa-chart-line text-blue-500"></i>
          نظرة عامة على البيانات
        </h4>
        {stats.totalDistance > 0 ? (
           <ResponsiveContainer width="100%" height="100%">
             <BarChart data={[
               { name: 'المسافة', val: stats.totalDistance / 10 },
               { name: 'اللترات', val: stats.totalLiters },
               { name: 'التكلفة/10', val: stats.totalCost / 10 }
             ]}>
               <CartesianGrid strokeDasharray="3 3" vertical={false} />
               <XAxis dataKey="name" axisLine={false} tickLine={false} />
               <YAxis hide />
               <Tooltip cursor={{fill: '#f1f5f9'}} />
               <Bar dataKey="val" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
             </BarChart>
           </ResponsiveContainer>
        ) : (
          <div className="h-full flex items-center justify-center text-slate-400">
            أضف تسجيلين على الأقل لعرض الرسم البياني
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';

interface Props {
  onAdd: (data: { date: string; odometer: number; liters: number; pricePerLiter: number }) => void;
  lastOdometer: number;
}

const RecordForm: React.FC<Props> = ({ onAdd, lastOdometer }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    odometer: lastOdometer > 0 ? lastOdometer : 0,
    liters: 0,
    pricePerLiter: 0
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.liters <= 0 || formData.odometer <= 0) return;
    onAdd(formData);
    setFormData(prev => ({ ...prev, liters: 0, pricePerLiter: 0 }));
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-md border border-slate-100">
      <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
        <i className="fas fa-plus-circle text-blue-600"></i>
        إضافة تفويله جديدة
      </h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-semibold text-slate-600 mb-1">التاريخ</label>
          <input 
            type="date" 
            required
            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={formData.date}
            onChange={e => setFormData({...formData, date: e.target.value})}
          />
        </div>
        <div>
          <label className="block text-sm font-semibold text-slate-600 mb-1">قراءة العداد (كم)</label>
          <input 
            type="number" 
            placeholder="مثال: 54000"
            required
            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={formData.odometer || ''}
            onChange={e => setFormData({...formData, odometer: parseFloat(e.target.value)})}
          />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">عدد اللترات</label>
            <input 
              type="number" 
              step="0.01"
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              value={formData.liters || ''}
              onChange={e => setFormData({...formData, liters: parseFloat(e.target.value)})}
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">سعر اللتر</label>
            <input 
              type="number" 
              step="0.01"
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              value={formData.pricePerLiter || ''}
              onChange={e => setFormData({...formData, pricePerLiter: parseFloat(e.target.value)})}
            />
          </div>
        </div>
        <button 
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-blue-200 flex items-center justify-center gap-2"
        >
          <i className="fas fa-check"></i>
          حفظ البيانات
        </button>
      </form>
    </div>
  );
};

export default RecordForm;

import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { FuelRecord, Statistics } from '../types';

interface Props {
  records: FuelRecord[];
  stats: Statistics;
}

const AIInsights: React.FC<Props> = ({ records, stats }) => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const getAIAdvice = async () => {
    if (records.length < 2) return;

    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `بناءً على بيانات استهلاك البنزين التالية لسيارتي:
      - متوسط الاستهلاك: ${stats.averageConsumption.toFixed(2)} لتر لكل 100 كم
      - تكلفة الكيلومتر: ${stats.costPerKm.toFixed(2)} جنيه مصري
      - إجمالي المسافة: ${stats.totalDistance} كم

      من فضلك قدم لي 3 نصائح عملية ومخصصة باللغة العربية لتقليل استهلاك الوقود وتحسين كفاءة السيارة. اجعل الرد منسقاً وسهلاً للقراءة.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setInsight(response.text || "عذراً، لم أتمكن من استخلاص نصائح حالياً.");
    } catch (err) {
      console.error(err);
      setInsight("حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-3xl shadow-xl text-white">
      <div className="flex items-center gap-3 mb-4">
        <div className="bg-indigo-500/20 p-2 rounded-lg border border-indigo-400/30">
          <i className="fas fa-robot text-indigo-400 text-xl"></i>
        </div>
        <h3 className="font-bold text-lg">تحليل الذكاء الاصطناعي</h3>
      </div>

      {insight ? (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
          <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap bg-white/5 p-4 rounded-xl border border-white/10">
            {insight}
          </div>
          <button 
            onClick={() => setInsight(null)}
            className="text-xs text-indigo-400 hover:text-indigo-300 font-bold uppercase tracking-wider flex items-center gap-1"
          >
            <i className="fas fa-redo text-[10px]"></i>
            تحديث النصائح
          </button>
        </div>
      ) : (
        <div className="space-y-4">
          <p className="text-slate-400 text-sm">
            احصل على نصائح ذكية مخصصة لسيارتك بناءً على أرقام استهلاكك الحقيقية.
          </p>
          <button 
            disabled={loading || records.length < 2}
            onClick={getAIAdvice}
            className={`w-full py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${
              records.length < 2 
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed' 
                : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-900/40'
            }`}
          >
            {loading ? (
              <i className="fas fa-circle-notch fa-spin"></i>
            ) : (
              <i className="fas fa-magic"></i>
            )}
            {records.length < 2 ? 'سجل تفويلتين لتفعيل الميزة' : 'عرض النصائح المخصصة'}
          </button>
        </div>
      )}
    </div>
  );
};

export default AIInsights;

export interface FuelRecord {
  id: string;
  date: string;
  startOdometer: number;
  endOdometer: number;
  dailyPrice: number;
}

export interface Statistics {
  totalDistance: number;
  totalCost: number;
  averageDailyPrice: number;
  tripsCount: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { FuelRecord, Statistics } from './types';
import Dashboard from './components/Dashboard';
import RecordForm from './components/RecordForm';
import HistoryTable from './components/HistoryTable';
import AIInsights from './components/AIInsights';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [records, setRecords] = useState<FuelRecord[]>(() => {
    const saved = localStorage.getItem('car_records');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('car_records', JSON.stringify(records));
  }, [records]);

  const stats = useMemo((): Statistics => {
    if (records.length === 0) {
      return { totalDistance: 0, totalCost: 0, averageDailyPrice: 0, tripsCount: 0 };
    }

    const totalDistance = records.reduce((acc, curr) => acc + (curr.endOdometer - curr.startOdometer), 0);
    const totalCost = records.reduce((acc, curr) => acc + curr.dailyPrice, 0);
    const averageDailyPrice = totalCost / records.length;

    return { totalDistance, totalCost, averageDailyPrice, tripsCount: records.length };
  }, [records]);

  const addRecord = (data: Omit<FuelRecord, 'id'>) => {
    const newRecord: FuelRecord = {
      ...data,
      id: uuidv4()
    };
    setRecords(prev => [newRecord, ...prev]);
  };

  const deleteRecord = (id: string) => {
    setRecords(prev => prev.filter(r => r.id !== id));
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-12 font-['Cairo']">
      <header className="bg-gradient-to-r from-emerald-600 to-teal-700 text-white py-8 px-4 shadow-lg mb-8">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <i className="fas fa-car-side text-3xl"></i>
            </div>
            <div>
              <h1 className="text-3xl font-bold tracking-tight">مساعد توفير البنزين</h1>
              <p className="text-emerald-50 opacity-90">احسب تكلفة مشوارك اليومي بدقة</p>
            </div>
          </div>
          <div className="bg-white/10 px-6 py-2 rounded-full border border-white/20 font-bold">
             {records.length} تسجيل في الأرشيف
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-8">
          <RecordForm onAdd={addRecord} lastEndOdometer={records[0]?.endOdometer || 0} />
          <AIInsights records={records} stats={stats} />
        </div>

        <div className="lg:col-span-8 space-y-8">
          <Dashboard stats={stats} />
          <HistoryTable records={records} onDelete={deleteRecord} />
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

interface Props {
  onAdd: (data: { date: string; startOdometer: number; endOdometer: number; dailyPrice: number }) => void;
  lastEndOdometer: number;
}

const RecordForm: React.FC<Props> = ({ onAdd, lastEndOdometer }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    startOdometer: lastEndOdometer || 0,
    endOdometer: 0
  });

  const [calculatedPrice, setCalculatedPrice] = useState(0);

  useEffect(() => {
    const diff = formData.endOdometer - formData.startOdometer;
    if (diff > 0) {
      setCalculatedPrice(diff / 12);
    } else {
      setCalculatedPrice(0);
    }
  }, [formData.startOdometer, formData.endOdometer]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.endOdometer <= formData.startOdometer) {
      alert("يجب أن تكون نهاية العداد أكبر من بدايته");
      return;
    }
    onAdd({
      ...formData,
      dailyPrice: calculatedPrice
    });
    setFormData(prev => ({
      ...prev,
      startOdometer: formData.endOdometer,
      endOdometer: 0
    }));
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-md border border-slate-100">
      <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
        <i className="fas fa-plus-circle text-emerald-600"></i>
        إضافة مشوار اليوم
      </h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-semibold text-slate-600 mb-1">تاريخ التفويله/المشوار</label>
          <input 
            type="date" 
            required
            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
            value={formData.date}
            onChange={e => setFormData({...formData, date: e.target.value})}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">بداية العداد</label>
            <input 
              type="number" 
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
              value={formData.startOdometer || ''}
              onChange={e => setFormData({...formData, startOdometer: parseFloat(e.target.value)})}
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">نهاية العداد</label>
            <input 
              type="number" 
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
              value={formData.endOdometer || ''}
              onChange={e => setFormData({...formData, endOdometer: parseFloat(e.target.value)})}
            />
          </div>
        </div>

        <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100">
          <div className="flex justify-between items-center">
            <span className="text-emerald-700 font-bold">سعر اليوم المتوقع:</span>
            <span className="text-2xl font-black text-emerald-600">{calculatedPrice.toFixed(2)} <small className="text-sm">ج.م</small></span>
          </div>
          <p className="text-[10px] text-emerald-500 mt-1">المعادلة: (النهاية - البداية) / 12</p>
        </div>

        <button 
          type="submit"
          className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-emerald-200 flex items-center justify-center gap-2"
        >
          <i className="fas fa-save"></i>
          حفظ البيانات في الأرشيف
        </button>
      </form>
    </div>
  );
};

export default RecordForm;

import React from 'react';
import { Statistics } from '../types';
import { ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

interface Props {
  stats: Statistics;
}

const Dashboard: React.FC<Props> = ({ stats }) => {
  const cards = [
    { label: 'إجمالي المسافة', value: `${stats.totalDistance.toLocaleString()} كم`, icon: 'fa-road', color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'إجمالي التكاليف', value: `${stats.totalCost.toLocaleString()} ج.م`, icon: 'fa-wallet', color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'متوسط سعر اليوم', value: `${stats.averageDailyPrice.toFixed(2)} ج.م`, icon: 'fa-chart-pie', color: 'text-amber-600', bg: 'bg-amber-50' },
    { label: 'عدد المشاوير', value: `${stats.tripsCount}`, icon: 'fa-list-ol', color: 'text-indigo-600', bg: 'bg-indigo-50' },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {cards.map((card, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-5 transition-transform hover:scale-[1.02]">
            <div className={`${card.bg} ${card.color} w-14 h-14 rounded-xl flex items-center justify-center text-2xl`}>
              <i className={`fas ${card.icon}`}></i>
            </div>
            <div>
