interface Props {
  records: FuelRecord[];
  refuels: RefuelRecord[];
}

const MonthlyReport: React.FC<Props> = ({ records, refuels }) => {
  // تجميع البيانات حسب الشهر والسنة
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const monthlyTripsCost = records
    .filter(r => {
      const d = new Date(r.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    })
    .reduce((acc, curr) => acc + curr.dailyPrice, 0);

  const monthlyRefuelTotal = refuels
    .filter(r => {
      const d = new Date(r.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    })
    .reduce((acc, curr) => acc + curr.amount, 0);

  const diff = monthlyRefuelTotal - monthlyTripsCost;
  const monthName = new Intl.DateTimeFormat('ar-EG', { month: 'long' }).format(new Date());

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center">
        <h2 className="text-2xl font-bold text-slate-800 mb-2">تقرير شهر {monthName} {currentYear}</h2>
        <p className="text-slate-500">ملخص المصاريف الفعلية مقابل استهلاك المشاوير</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border-r-4 border-rose-500">
          <p className="text-slate-500 text-sm font-bold">إجمالي التفويلات (فعلي)</p>
          <h3 className="text-2xl font-black text-rose-600 mt-2">{monthlyRefuelTotal.toLocaleString()} ج.م</h3>
          <p className="text-[10px] text-slate-400 mt-1">المبالغ التي دفعتها فعلياً في المحطة</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border-r-4 border-emerald-500">
          <p className="text-slate-500 text-sm font-bold">حساب المشاوير (تقديري)</p>
          <h3 className="text-2xl font-black text-emerald-600 mt-2">{monthlyTripsCost.toLocaleString()} ج.م</h3>
          <p className="text-[10px] text-slate-400 mt-1">التكلفة المحسوبة بناءً على الكيلومترات</p>
        </div>

        <div className={`p-6 rounded-2xl shadow-lg text-white ${diff >= 0 ? 'bg-amber-500' : 'bg-blue-600'}`}>
          <p className="opacity-90 text-sm font-bold">صافي الفرق (العجز/الفائض)</p>
          <h3 className="text-2xl font-black mt-2">{Math.abs(diff).toLocaleString()} ج.م</h3>
          <p className="text-[10px] mt-1 opacity-80">
            {diff >= 0 ? 'البنزين الموجود حالياً في السيارة (فائض)' : 'لقد استهلكت أكثر مما فولت (عجز)'}
          </p>
        </div>
      </div>

      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
        <h3 className="font-bold text-slate-800 mb-6 flex items-center gap-2">
          <i className="fas fa-chart-bar text-indigo-500"></i>
          تحليل الحالة المالية
        </h3>

        <div className="relative pt-1">
          <div className="flex mb-2 items-center justify-between">
            <div>
              <span className="text-xs font-semibold inline-block py-1 px-2 uppercase rounded-full text-emerald-600 bg-emerald-200">
                نسبة الاستهلاك من التفويل
              </span>
            </div>
            <div className="text-right">
              <span className="text-xs font-semibold inline-block text-emerald-600">
                {monthlyRefuelTotal > 0 ? ((monthlyTripsCost / monthlyRefuelTotal) * 100).toFixed(1) : 0}%
              </span>
            </div>
          </div>
          <div className="overflow-hidden h-4 mb-4 text-xs flex rounded-full bg-slate-100">
            <div 
              style={{ width: `${monthlyRefuelTotal > 0 ? Math.min((monthlyTripsCost / monthlyRefuelTotal) * 100, 100) : 0}%` }}
              className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-emerald-500 transition-all duration-1000"
            ></div>
          </div>
          <p className="text-xs text-slate-500 leading-relaxed">
            * إذا كانت النسبة 100% فهذا يعني أنك استهلكت كل ما دفعته في التفويلات.
            <br />
            * إذا كانت أقل من 100%، فلديك بنزين متبقي في التانك بقيمة {diff.toFixed(2)} ج.م.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
         <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100">
            <h4 className="font-bold text-blue-800 mb-2">نصيحة الشهر</h4>
            <p className="text-blue-700 text-sm">
               {diff > 0 
                ? "أنت تسير بمعدل جيد، الفائض يعني أنك تستهلك بنزين أقل من المتوقع بالنسبة لميزانيتك."
                : "تنبيه: التكلفة التقديرية لمشاويرك تخطت ما دفعته في التفويلات، راجع ضغط الإطارات أو طريقة القيادة."}
            </p>
         </div>
         <div className="bg-slate-800 p-6 rounded-2xl text-white">
            <h4 className="font-bold mb-2">كيف يتم الحساب؟</h4>
            <ul className="text-xs space-y-2 opacity-80">
              <li>1. يتم جمع كل مبالغ "التفويلات" المسجلة هذا الشهر.</li>
              <li>2. يتم جمع كل "أسعار اليوم" للمشاوير المسجلة هذا الشهر.</li>
              <li>3. النتيجة هي الفرق بين المدفوع (كاش) والمستهلك (كيلومترات).</li>
            </ul>
         </div>
      </div>
    </div>
  );
};

export default MonthlyReport;

import React, { useState, useMemo, useEffect } from 'react';
import { FuelRecord, RefuelRecord, Statistics } from './types';
import Dashboard from './components/Dashboard';
import RecordForm from './components/RecordForm';
import HistoryTable from './components/HistoryTable';
import AIInsights from './components/AIInsights';
import RefuelPage from './components/RefuelPage';
import MonthlyReport from './components/MonthlyReport';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'trips' | 'refuels' | 'monthly'>('trips');
  const [showAddModal, setShowAddModal] = useState(false);

  const [records, setRecords] = useState<FuelRecord[]>(() => {
    const saved = localStorage.getItem('car_records');
    return saved ? JSON.parse(saved) : [];
  });

  const [refuels, setRefuels] = useState<RefuelRecord[]>(() => {
    const saved = localStorage.getItem('refuel_records');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('car_records', JSON.stringify(records));
  }, [records]);

  useEffect(() => {
    localStorage.setItem('refuel_records', JSON.stringify(refuels));
  }, [refuels]);

  const stats = useMemo((): Statistics => {
    const totalDistance = records.reduce((acc, curr) => acc + (curr.endOdometer - curr.startOdometer), 0);
    const totalCost = records.reduce((acc, curr) => acc + curr.dailyPrice, 0);
    const averageDailyPrice = records.length > 0 ? totalCost / records.length : 0;
    const totalRefuelAmount = refuels.reduce((acc, curr) => acc + curr.amount, 0);

    return { 
      totalDistance, 
      totalCost, 
      averageDailyPrice, 
      tripsCount: records.length,
      totalRefuelAmount 
    };
  }, [records, refuels]);

  const addRecord = (data: Omit<FuelRecord, 'id'>) => {
    const newRecord: FuelRecord = { ...data, id: uuidv4() };
    setRecords(prev => [newRecord, ...prev]);
    setShowAddModal(false);
  };

  const addRefuel = (data: Omit<RefuelRecord, 'id'>) => {
    const newRefuel: RefuelRecord = { ...data, id: uuidv4() };
    setRefuels(prev => [newRefuel, ...prev]);
    setShowAddModal(false);
  };

  const deleteRecord = (id: string) => {
    if(confirm('هل تريد حذف هذا السجل؟')) {
      setRecords(prev => prev.filter(r => r.id !== id));
    }
  };

  const deleteRefuel = (id: string) => {
    if(confirm('هل تريد حذف هذه التفويلة؟')) {
      setRefuels(prev => prev.filter(r => r.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 pb-24 font-['Cairo'] overflow-x-hidden">
      {/* Android Style App Bar */}
      <header className="bg-emerald-600 text-white pt-4 pb-4 px-6 shadow-md sticky top-0 z-40 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <i className="fas fa-gas-pump text-xl"></i>
          <h1 className="text-xl font-bold tracking-wide">
            {activeTab === 'trips' && 'المشاوير'}
            {activeTab === 'refuels' && 'التفويلات'}
            {activeTab === 'monthly' && 'التقرير الشهري'}
          </h1>
        </div>
        <button onClick={() => window.location.reload()} className="p-2 hover:bg-white/10 rounded-full transition-colors">
          <i className="fas fa-sync-alt"></i>
        </button>
      </header>

      <main className="px-4 pt-6 max-w-2xl mx-auto">
        {activeTab === 'trips' && (
          <div className="space-y-6">
            <Dashboard stats={stats} />
            <AIInsights records={records} stats={stats} />
            <div className="flex items-center justify-between px-2">
              <h2 className="font-black text-slate-800">أحدث المشاوير</h2>
              <span className="text-xs text-slate-500">{records.length} سجل</span>
            </div>
            <HistoryTable records={records} onDelete={deleteRecord} />
          </div>
        )}

        {activeTab === 'refuels' && (
          <RefuelPage refuels={refuels} onAdd={addRefuel} onDelete={deleteRefuel} isAndroid={true} />
        )}

        {activeTab === 'monthly' && (
          <MonthlyReport records={records} refuels={refuels} />
        )}
      </main>

      {/* Floating Action Button (FAB) */}
      {(activeTab === 'trips' || activeTab === 'refuels') && (
        <button 
          onClick={() => setShowAddModal(true)}
          className="fixed bottom-24 left-6 w-14 h-14 bg-emerald-600 text-white rounded-full shadow-2xl flex items-center justify-center text-2xl z-50 active:scale-95 transition-transform"
        >
          <i className="fas fa-plus"></i>
        </button>
      )}

      {/* Android Modal for Adding Data */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/50 backdrop-blur-sm transition-opacity">
          <div className="bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-3xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black text-slate-800">إضافة جديد</h2>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 p-2">
                <i className="fas fa-times"></i>
              </button>
            </div>
            {activeTab === 'trips' ? (
              <RecordForm onAdd={addRecord} lastEndOdometer={records[0]?.endOdometer || 0} />
            ) : (
              <RefuelPage refuels={refuels} onAdd={addRefuel} onDelete={deleteRefuel} hideList={true} />
            )}
          </div>
        </div>
      )}

      {/* Bottom Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-6 py-2 flex justify-around items-center z-40 safe-area-bottom shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
        <button 
          onClick={() => setActiveTab('trips')}
          className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'trips' ? 'active-tab' : 'text-slate-400'}`}
        >
          <i className="fas fa-route text-lg"></i>
          <span className="text-[10px] font-bold">المشاوير</span>
        </button>
        <button 
          onClick={() => setActiveTab('refuels')}
          className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'refuels' ? 'active-tab' : 'text-slate-400'}`}
        >
          <i className="fas fa-gas-pump text-lg"></i>
          <span className="text-[10px] font-bold">التفويلات</span>
        </button>
        <button 
          onClick={() => setActiveTab('monthly')}
          className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'monthly' ? 'active-tab' : 'text-slate-400'}`}
        >
          <i className="fas fa-chart-bar text-lg"></i>
          <span className="text-[10px] font-bold">الشهر</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

