import React, { useState } from 'react';
import { RefuelRecord } from '../types';

interface Props {
  refuels: RefuelRecord[];
  onAdd: (data: Omit<RefuelRecord, 'id'>) => void;
  onDelete: (id: string) => void;
  isAndroid?: boolean;
  hideList?: boolean;
}

const RefuelPage: React.FC<Props> = ({ refuels, onAdd, onDelete, hideList = false }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    amount: 0,
    liters: 0
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.amount <= 0) return;
    onAdd(formData);
    setFormData({ ...formData, amount: 0, liters: 0 });
  };

  const totalAmount = refuels.reduce((acc, curr) => acc + curr.amount, 0);

  if (hideList) {
    return (
      <form onSubmit={handleSubmit} className="space-y-5">
        <div>
          <label className="block text-xs font-bold text-slate-500 mb-2">تاريخ التفويله</label>
          <input 
            type="date" 
            required
            className="w-full px-4 py-3 rounded-xl bg-slate-100 border-none focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold"
            value={formData.date}
            onChange={e => setFormData({...formData, date: e.target.value})}
          />
        </div>
        <div>
          <label className="block text-xs font-bold text-slate-500 mb-2">المبلغ المدفوع (ج.م)</label>
          <input 
            type="number" 
            required
            placeholder="0.00"
            className="w-full px-4 py-4 rounded-xl bg-slate-100 border-none focus:ring-2 focus:ring-blue-500 outline-none transition-all font-black text-blue-700 text-2xl"
            value={formData.amount || ''}
            onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})}
          />
        </div>
        <div>
          <label className="block text-xs font-bold text-slate-500 mb-2">عدد اللترات (اختياري)</label>
          <input 
            type="number" 
            step="0.01"
            placeholder="0"
            className="w-full px-4 py-3 rounded-xl bg-slate-100 border-none focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold"
            value={formData.liters || ''}
            onChange={e => setFormData({...formData, liters: parseFloat(e.target.value)})}
          />
        </div>
        <button 
          type="submit"
          className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-200 active:scale-95 transition-transform mt-4"
        >
          حفظ التفويلة
        </button>
      </form>
    );
  }

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-blue-700 p-6 rounded-3xl text-white shadow-lg relative overflow-hidden">
        <div className="relative z-10">
          <p className="opacity-80 text-xs font-bold mb-1 uppercase tracking-widest">إجمالي مصاريف البنزين</p>
          <h2 className="text-4xl font-black">{totalAmount.toLocaleString()} <small className="text-lg font-normal">ج.م</small></h2>
          <div className="mt-4 flex gap-4 text-xs font-bold">
            <span className="bg-white/20 px-3 py-1 rounded-full">مرات التفويل: {refuels.length}</span>
          </div>
        </div>
        <i className="fas fa-gas-pump absolute -bottom-4 -left-4 text-8xl opacity-10 rotate-12"></i>
      </div>

      <div className="flex items-center justify-between px-2">
        <h2 className="font-black text-slate-800">سجل التفويلات</h2>
      </div>

      <div className="space-y-3">
        {refuels.length > 0 ? refuels.map(refuel => (
          <div key={refuel.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex justify-between items-center">
            <div className="flex gap-4 items-center">
              <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center">
                <i className="fas fa-fill-drip text-sm"></i>
              </div>
              <div>
                <div className="text-sm font-bold text-slate-800">{refuel.date}</div>
                <div className="text-[10px] text-slate-400 font-medium">
                  {refuel.liters ? `${refuel.liters} لتر` : 'تفويلة غير محددة اللترات'}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-sm font-black text-blue-600">{refuel.amount.toLocaleString()} <small className="text-[8px]">ج.م</small></div>
              <button 
                onClick={() => onDelete(refuel.id)}
                className="w-8 h-8 text-slate-300 hover:text-rose-500"
              >
                <i className="fas fa-trash-alt text-sm"></i>
              </button>
            </div>
          </div>
        )) : (
          <div className="bg-white rounded-3xl p-12 text-center border border-slate-200">
            <i className="fas fa-list-ul text-4xl text-slate-100 mb-4"></i>
            <p className="text-slate-400 text-sm">لا توجد تفويلات محفوظة</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default RefuelPage;

import React from 'react';
import { FuelRecord, RefuelRecord } from '../types';

interface Props {
  records: FuelRecord[];
  refuels: RefuelRecord[];
}

const MonthlyReport: React.FC<Props> = ({ records, refuels }) => {
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // إجمالي تكلفة المشاوير (المحسوبة بالمعادلة)
  const monthlyTripsCost = records
    .filter(r => {
      const d = new Date(r.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    })
    .reduce((acc, curr) => acc + curr.dailyPrice, 0);

  // إجمالي مبالغ التفويل (المدفوعة فعلياً)
  const monthlyRefuelTotal = refuels
    .filter(r => {
      const d = new Date(r.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    })
    .reduce((acc, curr) => acc + curr.amount, 0);

  // الحسبة المطلوبة: التفويل - المشاوير
  const balance = monthlyRefuelTotal - monthlyTripsCost;
  const monthName = new Intl.DateTimeFormat('ar-EG', { month: 'long' }).format(new Date());

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header Card */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200 text-center">
        <span className="bg-emerald-100 text-emerald-700 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">ملخص الشهر الحالي</span>
        <h2 className="text-2xl font-black text-slate-800 mt-3">{monthName} {currentYear}</h2>
      </div>

      {/* Main Calculation Card */}
      <div className={`p-8 rounded-[2rem] shadow-xl text-white relative overflow-hidden transition-all ${balance >= 0 ? 'bg-emerald-600' : 'bg-rose-600'}`}>
        <div className="relative z-10">
          <p className="opacity-80 text-sm font-bold mb-2">الرصيد المتبقي (بنزين في التانك)</p>
          <div className="flex items-baseline gap-2">
            <h3 className="text-5xl font-black tracking-tighter">
              {Math.abs(balance).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </h3>
            <span className="text-lg opacity-80 font-bold">ج.م</span>
          </div>
          <p className="mt-4 text-xs font-medium opacity-90 leading-relaxed">
            {balance >= 0 
              ? "لديك فائض! هذا المبلغ يمثل قيمة البنزين الموجود حالياً في سيارتك ولم تستهلكه بعد." 
              : "تنبيه: لقد استهلكت بنزين بقيمة أكبر مما قمت بتفويله (عجز في الميزانية)."}
          </p>
        </div>
        <i className={`fas ${balance >= 0 ? 'fa-chart-line' : 'fa-exclamation-triangle'} absolute -bottom-6 -left-6 text-[10rem] opacity-10`}></i>
      </div>

      {/* Breakdown Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
          <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-3">
            <i className="fas fa-receipt text-sm"></i>
          </div>
          <p className="text-slate-400 text-[10px] font-bold uppercase">إجمالي التفويل</p>
          <h4 className="text-lg font-black text-slate-800 mt-1">{monthlyRefuelTotal.toLocaleString()} <small className="text-[10px]">ج.م</small></h4>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
          <div className="w-10 h-10 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center mb-3">
            <i className="fas fa-car-side text-sm"></i>
          </div>
          <p className="text-slate-400 text-[10px] font-bold uppercase">إجمالي المشاوير</p>
          <h4 className="text-lg font-black text-slate-800 mt-1">{monthlyTripsCost.toLocaleString()} <small className="text-[10px]">ج.م</small></h4>
        </div>
      </div>

      {/* Visual Analytics */}
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <h3 className="text-sm font-black text-slate-800 mb-4 flex items-center gap-2">
          <i className="fas fa-percentage text-emerald-500"></i>
          معدل الاستهلاك الفعلي
        </h3>

        <div className="relative h-3 w-full bg-slate-100 rounded-full overflow-hidden">
          <div 
            className={`h-full transition-all duration-1000 rounded-full ${balance >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`}
            style={{ width: `${monthlyRefuelTotal > 0 ? Math.min((monthlyTripsCost / monthlyRefuelTotal) * 100, 100) : 0}%` }}
          ></div>
        </div>

