              </button>
            </div>
            {activeTab === 'trips' ? (
              <RecordForm onAdd={addRecord} lastEndOdometer={records[0]?.endOdometer || 0} />
            ) : (
              <RefuelPage refuels={filteredRefuels} onAdd={addRefuel} onDelete={() => {}} hideList={true} />
