import React, { useState, useMemo, useEffect } from 'react';
import { FuelRecord, RefuelRecord, Statistics, User } from './types';
import Dashboard from './components/Dashboard';
import RecordForm from './components/RecordForm';
import HistoryTable from './components/HistoryTable';
import AIInsights from './components/AIInsights';
import RefuelPage from './components/RefuelPage';
import MonthlyReport from './components/MonthlyReport';
import UserProfile from './components/UserProfile';
import LoginScreen from './components/LoginScreen';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'trips' | 'refuels' | 'monthly' | 'profile'>('trips');
  const [showAddModal, setShowAddModal] = useState(false);

  // Global fuel price managed by admin
  const [globalFuelPrice, setGlobalFuelPrice] = useState<number>(() => {
    const saved = localStorage.getItem('global_fuel_price');
    return saved ? parseFloat(saved) : 12.25;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('app_users');
    return saved ? JSON.parse(saved) : [
      { id: '1', username: 'admin', password: 'admin', role: 'main', createdAt: new Date().toISOString() }
    ];
  });

  const [records, setRecords] = useState<FuelRecord[]>(() => {
    const saved = localStorage.getItem('car_records');
    return saved ? JSON.parse(saved) : [];
  });

  const [refuels, setRefuels] = useState<RefuelRecord[]>(() => {
    const saved = localStorage.getItem('refuel_records');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('app_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('car_records', JSON.stringify(records));
  }, [records]);

  useEffect(() => {
    localStorage.setItem('refuel_records', JSON.stringify(refuels));
  }, [refuels]);

  useEffect(() => {
    localStorage.setItem('global_fuel_price', globalFuelPrice.toString());
  }, [globalFuelPrice]);

  const filteredRecords = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === 'main') return records;
    return records.filter(r => r.userId === currentUser.id);
  }, [records, currentUser]);

  const filteredRefuels = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === 'main') return refuels;
    return refuels.filter(r => r.userId === currentUser.id);
  }, [refuels, currentUser]);

  const stats = useMemo((): Statistics => {
    const totalDistance = filteredRecords.reduce((acc, curr) => acc + (curr.endOdometer - curr.startOdometer), 0);
    const totalCost = filteredRecords.reduce((acc, curr) => acc + curr.dailyPrice, 0);
    const averageDailyPrice = filteredRecords.length > 0 ? totalCost / filteredRecords.length : 0;
    const totalRefuelAmount = filteredRefuels.reduce((acc, curr) => acc + curr.amount, 0);

    return { 
      totalDistance, 
      totalCost, 
      averageDailyPrice, 
      tripsCount: filteredRecords.length,
      totalRefuelAmount 
    };
  }, [filteredRecords, filteredRefuels]);

  if (!currentUser) {
    return <LoginScreen onLogin={(user) => {
      setCurrentUser(user);
      localStorage.setItem('current_user', JSON.stringify(user));
    }} users={users} />;
  }

  const addRecord = (data: Omit<FuelRecord, 'id' | 'userId'>) => {
    const newRecord: FuelRecord = { ...data, id: uuidv4(), userId: currentUser.id };
    setRecords(prev => [newRecord, ...prev]);
    setShowAddModal(false);
  };

  const addRefuel = (data: Omit<RefuelRecord, 'id' | 'userId'>) => {
    const newRefuel: RefuelRecord = { ...data, id: uuidv4(), userId: currentUser.id };
    setRefuels(prev => [newRefuel, ...prev]);
    setShowAddModal(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('current_user');
  };

  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
  };

  const updateUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
      localStorage.setItem('current_user', JSON.stringify(updatedUser));
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 pb-24 font-['Cairo'] overflow-x-hidden">
      <header className="bg-emerald-600 text-white pt-4 pb-4 px-6 shadow-md sticky top-0 z-40 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <i className="fas fa-gas-pump text-xl"></i>
          <h1 className="text-xl font-bold tracking-wide">
            {activeTab === 'trips' && 'المشاوير'}
            {activeTab === 'refuels' && 'التفويلات'}
            {activeTab === 'monthly' && 'التقرير الشهري'}
            {activeTab === 'profile' && 'الملف الشخصي'}
          </h1>
        </div>
        <div className="flex items-center gap-2">
           <span className="text-[10px] bg-white/20 px-2 py-0.5 rounded-full font-bold">
              {currentUser.role === 'main' ? 'أساسي' : 'عادي'}
           </span>
        </div>
      </header>

      <main className="px-4 pt-6 max-w-2xl mx-auto">
        {activeTab === 'trips' && (
          <div className="space-y-6">
            <Dashboard stats={stats} />
            <AIInsights records={filteredRecords} stats={stats} />
            <div className="flex items-center justify-between px-2">
              <h2 className="font-black text-slate-800">أحدث المشاوير</h2>
              <span className="text-xs text-slate-500">{filteredRecords.length} سجل</span>
            </div>
            <HistoryTable records={filteredRecords} onDelete={(id) => setRecords(prev => prev.filter(r => r.id !== id))} />
          </div>
        )}

        {activeTab === 'refuels' && (
          <RefuelPage refuels={filteredRefuels} onAdd={addRefuel} onDelete={(id) => setRefuels(prev => prev.filter(r => r.id !== id))} isAndroid={true} />
        )}

        {activeTab === 'monthly' && (
          <MonthlyReport records={filteredRecords} refuels={filteredRefuels} />
        )}

        {activeTab === 'profile' && (
          <UserProfile 
            currentUser={currentUser} 
            users={users} 
            onLogout={handleLogout} 
            onAddUser={addUser}
            onUpdateUser={updateUser}
            allRecords={records}
            allRefuels={refuels}
            globalFuelPrice={globalFuelPrice}
            onUpdateFuelPrice={setGlobalFuelPrice}
          />
        )}
      </main>

      {(activeTab === 'trips' || activeTab === 'refuels') && (
        <button 
          onClick={() => setShowAddModal(true)}
          className="fixed bottom-24 left-6 w-14 h-14 bg-emerald-600 text-white rounded-full shadow-2xl flex items-center justify-center text-2xl z-50 active:scale-95 transition-transform"
        >
          <i className="fas fa-plus"></i>
        </button>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/50 backdrop-blur-sm transition-opacity">
          <div className="bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-3xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black text-slate-800">إضافة جديد</h2>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 p-2">
                <i className="fas fa-times"></i>
              </button>
            </div>
            {activeTab === 'trips' ? (
              <RecordForm 
                onAdd={addRecord} 
                lastEndOdometer={records[0]?.endOdometer || 0} 
                fixedFuelPrice={globalFuelPrice}
              />
            ) : (
              <RefuelPage refuels={filteredRefuels} onAdd={addRefuel} onDelete={() => {}} hideList={true} />
            )}
          </div>
        </div>
      )}

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-6 py-2 flex justify-around items-center z-40 safe-area-bottom shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveTab('trips')} className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'trips' ? 'active-tab' : 'text-slate-400'}`}>
          <i className="fas fa-route text-lg"></i>
          <span className="text-[10px] font-bold">المشاوير</span>
        </button>
        <button onClick={() => setActiveTab('refuels')} className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'refuels' ? 'active-tab' : 'text-slate-400'}`}>
          <i className="fas fa-gas-pump text-lg"></i>
          <span className="text-[10px] font-bold">التفويلات</span>
        </button>
        <button onClick={() => setActiveTab('monthly')} className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'monthly' ? 'active-tab' : 'text-slate-400'}`}>
          <i className="fas fa-chart-bar text-lg"></i>
          <span className="text-[10px] font-bold">الشهر</span>
        </button>
        <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center gap-1 p-2 transition-all ${activeTab === 'profile' ? 'active-tab' : 'text-slate-400'}`}>
          <i className="fas fa-user text-lg"></i>
          <span className="text-[10px] font-bold">الحساب</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

interface Props {
  onAdd: (data: { date: string; startOdometer: number; endOdometer: number; pricePerLiter: number; dailyPrice: number }) => void;
  lastEndOdometer: number;
  fixedFuelPrice: number;
}

const RecordForm: React.FC<Props> = ({ onAdd, lastEndOdometer, fixedFuelPrice }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    startOdometer: lastEndOdometer || 0,
    endOdometer: 0,
  });

  const [calculatedPrice, setCalculatedPrice] = useState(0);

  useEffect(() => {
    const distance = formData.endOdometer - formData.startOdometer;
    if (distance > 0 && fixedFuelPrice > 0) {
      // المعادلة: ((النهاية - البداية) / 12) * سعر اللتر المحدد من المسؤول
      const price = (distance / 12) * fixedFuelPrice;
      setCalculatedPrice(price);
    } else {
      setCalculatedPrice(0);
    }
  }, [formData.startOdometer, formData.endOdometer, fixedFuelPrice]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.endOdometer <= formData.startOdometer) {
      alert("يجب أن تكون نهاية العداد أكبر من بدايته");
      return;
    }
    onAdd({
      ...formData,
      pricePerLiter: fixedFuelPrice,
      dailyPrice: calculatedPrice
    });
    setFormData(prev => ({
      ...prev,
      startOdometer: formData.endOdometer,
      endOdometer: 0
    }));
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-md border border-slate-100">
      <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
        <i className="fas fa-gas-pump text-emerald-600"></i>
        تسجيل مشوار جديد
      </h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-semibold text-slate-600 mb-1">تاريخ اليوم</label>
          <input 
            type="date" 
            required
            className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
            value={formData.date}
            onChange={e => setFormData({...formData, date: e.target.value})}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">بداية العداد</label>
            <input 
              type="number" 
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold"
              value={formData.startOdometer || ''}
              onChange={e => setFormData({...formData, startOdometer: parseFloat(e.target.value)})}
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-600 mb-1">نهاية العداد</label>
            <input 
              type="number" 
              required
              className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold"
              value={formData.endOdometer || ''}
              onChange={e => setFormData({...formData, endOdometer: parseFloat(e.target.value)})}
            />
          </div>
        </div>

        <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 flex justify-between items-center">
          <span className="text-xs font-bold text-slate-500">سعر اللتر (إدارة):</span>
          <span className="text-sm font-black text-slate-700">{fixedFuelPrice} ج.م</span>
        </div>

        <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100">
          <div className="flex justify-between items-center">
            <span className="text-emerald-700 font-bold">التكلفة المحسوبة:</span>
            <div className="text-right">
              <span className="text-2xl font-black text-emerald-600">{calculatedPrice.toFixed(2)} <small className="text-sm">ج.م</small></span>
            </div>
          </div>
          <div className="mt-2 text-[10px] text-emerald-500 flex justify-between">
            <span>المسافة: {(formData.endOdometer - formData.startOdometer) > 0 ? (formData.endOdometer - formData.startOdometer) : 0} كم</span>
            <span>المعادلة: (المسافة / 12) × {fixedFuelPrice}</span>
          </div>
        </div>

        <button 
          type="submit"
          className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-emerald-200 flex items-center justify-center gap-2"
        >
          <i className="fas fa-save"></i>
          حفظ المشوار
        </button>
      </form>
    </div>
  );
};

export default RecordForm;

import React, { useState, useMemo } from 'react';
import { User, FuelRecord, RefuelRecord } from '../types';
import { v4 as uuidv4 } from 'uuid';

interface Props {
  currentUser: User;
  users: User[];
  onLogout: () => void;
  onAddUser: (user: User) => void;
  onUpdateUser: (user: User) => void;
  allRecords: FuelRecord[];
  allRefuels: RefuelRecord[];
  globalFuelPrice: number;
  onUpdateFuelPrice: (price: number) => void;
}

const UserProfile: React.FC<Props> = ({ 
  currentUser, 
  users, 
  onLogout, 
  onAddUser, 
  onUpdateUser, 
  allRecords, 
  allRefuels,
  globalFuelPrice,
  onUpdateFuelPrice
}) => {
  const [showAddUser, setShowAddUser] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({ username: '', password: '', role: 'regular' as const });
  const [editData, setEditData] = useState({ username: '', password: '' });
  const [successMsg, setSuccessMsg] = useState('');

  // Local state for price input
  const [tempPrice, setTempPrice] = useState(globalFuelPrice.toString());

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    onAddUser({
      id: uuidv4(),
      ...newUser,
      createdAt: new Date().toISOString()
    });
    setNewUser({ username: '', password: '', role: 'regular' });
    setShowAddUser(false);
    setSuccessMsg('تمت إضافة المستخدم بنجاح');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePriceUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price > 0) {
      onUpdateFuelPrice(price);
      setSuccessMsg('تم تحديث سعر البنزين لجميع السائقين');
      setTimeout(() => setSuccessMsg(''), 3000);
    }
  };

  const startEditing = (user: User) => {
    setEditingUserId(user.id);
    setEditData({ username: user.username, password: user.password || '' });
  };

  const handleUpdateUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUserId) return;

    const targetUser = users.find(u => u.id === editingUserId);
    if (targetUser) {
      onUpdateUser({
        ...targetUser,
        username: editData.username,
        password: editData.password
      });
      setEditingUserId(null);
      setSuccessMsg('تم تحديث البيانات بنجاح');
      setTimeout(() => setSuccessMsg(''), 3000);
    }
  };

  const usersStats = useMemo(() => {
    return users.map(user => {
      const userRecords = allRecords.filter(r => {
        const d = new Date(r.date);
        return r.userId === user.id && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      });

      const userRefuels = allRefuels.filter(r => {
        const d = new Date(r.date);
        return r.userId === user.id && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      });

      const totalSpent = userRecords.reduce((acc, curr) => acc + curr.dailyPrice, 0);
      const totalRefueled = userRefuels.reduce((acc, curr) => acc + curr.amount, 0);
      const balance = totalRefueled - totalSpent;

      return {
        ...user,
        totalSpent,
        totalRefueled,
        balance,
        tripsCount: userRecords.length
      };
    });
  }, [users, allRecords, allRefuels, currentMonth, currentYear]);

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-500">
      {successMsg && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 bg-emerald-500 text-white p-3 rounded-2xl text-xs font-bold text-center shadow-lg animate-bounce z-[100] w-2/3">
          {successMsg}
        </div>
      )}

      {/* Profile Card */}
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200">
        {editingUserId !== currentUser.id ? (
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-2xl font-black">
              {currentUser.username[0].toUpperCase()}
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h2 className="text-xl font-black text-slate-800">{currentUser.username}</h2>
                <button onClick={() => startEditing(currentUser)} className="w-7 h-7 bg-slate-50 text-slate-400 rounded-full flex items-center justify-center text-[10px]"><i className="fas fa-pen"></i></button>
              </div>
              <p className="text-xs text-slate-400">منذ: {new Date(currentUser.createdAt).toLocaleDateString('ar-EG')}</p>
            </div>
            <button onClick={onLogout} className="w-10 h-10 bg-slate-100 text-slate-400 rounded-xl flex items-center justify-center"><i className="fas fa-sign-out-alt"></i></button>
          </div>
        ) : (
          <form onSubmit={handleUpdateUser} className="space-y-4">
             <div className="flex justify-between items-center"><h3 className="font-black text-slate-800 text-sm">تعديل بياناتي</h3><button type="button" onClick={() => setEditingUserId(null)} className="text-xs text-slate-400">إلغاء</button></div>
             <input className="w-full px-4 py-3 rounded-xl bg-slate-50 outline-none text-right font-bold text-sm" value={editData.username} onChange={e => setEditData({...editData, username: e.target.value})} required />
             <input type="text" className="w-full px-4 py-3 rounded-xl bg-slate-50 outline-none text-right font-bold text-sm" value={editData.password} onChange={e => setEditData({...editData, password: e.target.value})} required />
             <button className="w-full bg-slate-800 text-white py-3 rounded-xl font-black text-sm">حفظ</button>
          </form>
        )}
      </div>

      {currentUser.role === 'main' && (
        <>
          {/* Admin: Global Fuel Price Control */}
          <div className="bg-slate-900 p-6 rounded-[2rem] text-white shadow-xl relative overflow-hidden">
             <div className="relative z-10">
                <div className="flex items-center gap-2 mb-4">
                  <i className="fas fa-gas-pump text-emerald-400"></i>
                  <h3 className="font-black text-sm">تحديد سعر البنزين (للكل)</h3>
                </div>
                <form onSubmit={handlePriceUpdate} className="flex gap-3">
                  <input 
                    type="number" 
                    step="0.01"
                    className="flex-1 bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-center font-black text-xl outline-none focus:ring-2 focus:ring-emerald-500"
                    value={tempPrice}
                    onChange={e => setTempPrice(e.target.value)}
                  />
                  <button className="bg-emerald-600 px-6 py-3 rounded-xl font-black text-xs shadow-lg active:scale-95 transition-transform">تحديث</button>
                </form>
                <p className="text-[10px] opacity-50 mt-3 text-center">هذا السعر سيطبق تلقائياً على جميع مشاوير السائقين</p>
             </div>
             <i className="fas fa-coins absolute -bottom-4 -left-4 text-7xl opacity-10"></i>
          </div>

          {/* Admin: Drivers Monthly Overview */}
          <div className="space-y-4">
            <h3 className="font-black text-slate-800 text-sm px-2">حسابات السائقين - الشهر الحالي</h3>
            <div className="grid grid-cols-1 gap-3">
              {usersStats.map(u => (
                <div key={u.id} className="bg-white p-4 rounded-3xl border border-slate-200 shadow-sm flex flex-col gap-3">
                  <div className="flex justify-between items-center border-b border-slate-50 pb-2">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-600">
                        {u.username[0].toUpperCase()}
                      </div>
                      <span className="font-black text-slate-800 text-sm">{u.username}</span>
                    </div>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${u.balance >= 0 ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                      {u.balance >= 0 ? 'فائض' : 'عجز'}
                    </span>
                  </div>
                  <div className="grid grid-cols-3 gap-2 text-center">
                    <div><p className="text-[8px] text-slate-400 font-bold uppercase">تفويل</p><p className="text-xs font-black text-blue-600">{u.totalRefueled.toLocaleString()}</p></div>
                    <div><p className="text-[8px] text-slate-400 font-bold uppercase">استهلاك</p><p className="text-xs font-black text-amber-600">{u.totalSpent.toLocaleString()}</p></div>
                    <div><p className="text-[8px] text-slate-400 font-bold uppercase">الرصيد</p><p className={`text-xs font-black ${u.balance >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>{Math.abs(u.balance).toLocaleString()}</p></div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="space-y-6 pt-4">
            <div className="flex items-center justify-between px-2">
              <h3 className="font-black text-slate-800">إدارة المستخدمين</h3>
              <button onClick={() => setShowAddUser(!showAddUser)} className="text-xs bg-emerald-600 text-white px-3 py-1.5 rounded-full font-bold">{showAddUser ? 'إلغاء' : 'إضافة مستخدم'}</button>
            </div>
            {showAddUser && (
              <form onSubmit={handleAddUser} className="bg-white p-6 rounded-3xl shadow-md border-2 border-emerald-100 space-y-4">
                <input placeholder="اسم المستخدم" className="w-full px-4 py-3 rounded-xl bg-slate-50 outline-none text-right font-bold text-sm" value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} required />
                <input type="text" placeholder="كلمة السر" className="w-full px-4 py-3 rounded-xl bg-slate-50 outline-none text-right font-bold text-sm" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} required />
                <select className="w-full px-4 py-3 rounded-xl bg-slate-50 outline-none font-bold text-right text-sm" value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as any})}>
                  <option value="regular">سائق عادي</option>
                  <option value="main">مسؤول أساسي</option>
                </select>
                <button className="w-full bg-emerald-600 text-white py-3 rounded-xl font-black">حفظ المستخدم</button>
              </form>
            )}
            <div className="space-y-3">
              {users.map(u => u.id !== currentUser.id && (
                <div key={u.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-600">{u.username[0].toUpperCase()}</div>
                    <div>
                      <div className="text-sm font-black text-slate-800">{u.username}</div>
                      <div className="text-[10px] text-slate-400 font-bold">{u.role === 'main' ? 'مسؤول' : 'سائق'}</div>
                    </div>
                  </div>
                  <button onClick={() => startEditing(u)} className="w-8 h-8 bg-slate-50 text-slate-400 rounded-lg flex items-center justify-center text-[10px]"><i className="fas fa-edit"></i></button>
                </div>
              ))}
            </div>
          </div>
        </>
      )}

      {currentUser.role !== 'main' && (
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
           <div className="flex items-center gap-3 mb-4">
              <div className="w-8 h-8 bg-blue-50 text-blue-500 rounded-lg flex items-center justify-center"><i className="fas fa-shield-alt text-xs"></i></div>
              <h3 className="font-bold text-slate-800 text-sm">صلاحياتك</h3>
